resource "aws_iam_user" "raynor" {
  name = "raynor-${var.cgid}"
}

resource "aws_iam_access_key" "raynor" {
  user = aws_iam_user.raynor.name
}


resource "aws_iam_policy" "versioned_policy" {
  name        = "cg-raynor-policy-${var.cgid}"
  description = "cg-raynor-policy"
  policy      = file("policies/v1.json")
}

resource "aws_iam_user_policy_attachment" "raynor_attachment" {
  user       = aws_iam_user.raynor.name
  policy_arn = aws_iam_policy.versioned_policy.arn
}

resource "null_resource" "policy_version" {
  provisioner "local-exec" {
    command = "aws iam create-policy-version --policy-arn ${aws_iam_policy.versioned_policy.arn} --policy-document file://policies/v2.json --no-set-as-default --profile ${var.profile} --region ${var.region}"
  }

  provisioner "local-exec" {
    command = "aws iam create-policy-version --policy-arn ${aws_iam_policy.versioned_policy.arn} --policy-document file://policies/v3.json --no-set-as-default --profile ${var.profile} --region ${var.region}"
  }

  provisioner "local-exec" {
    command = "aws iam create-policy-version --policy-arn ${aws_iam_policy.versioned_policy.arn} --policy-document file://policies/v4.json --no-set-as-default --profile ${var.profile} --region ${var.region}"
  }

  provisioner "local-exec" {
    command = "aws iam create-policy-version --policy-arn ${aws_iam_policy.versioned_policy.arn} --policy-document file://policies/v5.json --no-set-as-default --profile ${var.profile} --region ${var.region}"
  }
}

output "raynor_access_key_id" {
  description = "The access key ID for the Raynor user"
  value       = aws_iam_access_key.raynor.id
}

output "raynor_secret_access_key" {
  description = "The secret access key for the Raynor user"
  value       = aws_iam_access_key.raynor.secret
  sensitive   = true
}

terraform {
  required_version = ">= 1.5"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0.0"
    }
    local = {
      source  = "hashicorp/local"
      version = ">= 2.5.0"
    }
    null = {
      source  = "hashicorp/null"
      version = ">= 3.2.0"
    }
  }
}

provider "aws" {
  profile = var.profile
  region  = var.region

  default_tags {
    tags = {
      Stack    = var.stack-name
      Scenario = var.scenario-name
    }
  }
}

variable "profile" {
  description = "The AWS profile to use"
  type        = string
}

variable "cgid" {
  description = "CGID variable for unique naming"
  type        = string
}

variable "region" {
  description = "The AWS region to deploy to"
  default     = "us-east-1"
  type        = string
}

variable "stack-name" {
  description = "Name of the CloudGoat stack"
  default     = "CloudGoat"
  type        = string
}

variable "scenario-name" {
  description = "Name of the scenario"
  default     = "iam-privesc-by-rollback"
  type        = string
}
